#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static inline uint64_t rdtsc_relaxed(void) {
    unsigned lo, hi;
    __asm__ __volatile__("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}

static inline uint64_t rdtscp_ordered(void) {
    unsigned lo, hi, aux;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi), "=c"(aux));
    return ((uint64_t)hi << 32) | lo;
}

static int cmp_u64(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}

static void summarize(const char *name, uint64_t *v, size_t n) {
    qsort(v, n, sizeof(*v), cmp_u64);
    unsigned __int128 sum = 0;
    for (size_t i = 0; i < n; i++) sum += v[i];
    printf("%s min=%lu p01=%lu p50=%lu p90=%lu p99=%lu max=%lu mean=%.2f\n",
           name,
           v[0], v[n / 100], v[n / 2], v[(n * 90) / 100], v[(n * 99) / 100], v[n - 1],
           (double)sum / (double)n);
}

int main(void) {
    const size_t n = 1000000;
    uint64_t *a = malloc(n * sizeof(*a));
    uint64_t *b = malloc(n * sizeof(*b));
    if (!a || !b) return 1;

    for (size_t i = 0; i < 10000; i++) (void)rdtsc_relaxed();

    for (size_t i = 0; i < n; i++) {
        uint64_t t0 = rdtsc_relaxed();
        uint64_t t1 = rdtsc_relaxed();
        a[i] = t1 - t0;
    }
    for (size_t i = 0; i < n; i++) {
        uint64_t t0 = rdtscp_ordered();
        uint64_t t1 = rdtscp_ordered();
        b[i] = t1 - t0;
    }

    summarize("rdtsc->rdtsc", a, n);
    summarize("rdtscp->rdtscp", b, n);
    free(a);
    free(b);
    return 0;
}

