        assert_eq!(
            prefill_trace[0]["prefill_completion_tsc_ticks"],
            serde_json::Value::from(123)
        );
        assert_eq!(
            prefill_trace[0]["post_submit_completion_tsc_ticks"],
            serde_json::Value::from(23)
        );
    }
}

