        if status != DSA_COMP_NONE {
            return DsaCompletionStatus::mask(status);
        }

        spins += 1;
        if spins >= MAX_SPINS {
            eprintln!("poll completion: timeout after {} spins", spins);
            return 0xFF;
        }
        core::hint::spin_loop();
    }
}

