pub fn completion_flags_no_cache_control() -> DsaFlags {
    DsaFlag::RequestCompletionRecord | DsaFlag::CompletionRecordAddressValid
}

impl crate::submit::WqPortal {
    /// Submit a DSA descriptor through the local hw-eval portal.
