fn parse_usize_list(
    s: &str,
    flag: &'static str,
    require_positive: bool,
) -> Result<Vec<usize>, BenchmarkConfigError> {
    let mut values = Vec::new();

    for token in s.split(',') {
        let trimmed = token.trim();
        if trimmed.is_empty() {
            return Err(BenchmarkConfigError::EmptyListToken {
                flag,
                raw: s.to_owned(),
            });
